/**
 * @type {Map}
 * @private
 */
export const $broadcastEvents = new Map();
/**
 * @type {array}
 * @private
 */
const $array = [];
/**
 * @return {array}
 * @method
 * @private
 */
export const $getArray = () => {
    return $array.length
        ? $array.pop()
        : [];
};
/**
 * @return {void}
 * @method
 * @private
 */
export const $poolArray = (array) => {
    if (10 > $array.length) {
        array.length = 0;
        $array.push(array);
    }
};
/**
 * @type {IEvent}
 * @private
 */
let $event = null;
/**
 * @description アクティブなイベントオブジェクをセット
 *              Set the active event object
 *
 * @param  {IEvent} event
 * @return {void}
 * @method
 * @protected
 */
export const $setEvent = (event) => {
    $event = event;
};
/**
 * @description アクティブなイベントオブジェクを取得
 *              Get the active event object
 *
 * @return {IEvent}
 * @method
 * @protected
 */
export const $getEvent = () => {
    return $event;
};
